<?php require_once __DIR__.'/../../includes/functions.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)$_POST['name']);if($name){$s=db()->prepare('INSERT INTO categories(name,slug,description,status) VALUES(?,?,?,?)');$s->execute([$name,slug($name),trim((string)$_POST['description']),'active']);flash('success','Category added.');}redirect('index.php');}if(isset($_GET['delete'])){db()->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_GET['delete']]);redirect('index.php');}$rows=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$title='Categories';include __DIR__.'/../../includes/header.php';?><main class="container py-5"><h1 class="display-serif">Categories</h1><div class="row g-4"><div class="col-md-5"><div class="card p-4"><form method="post"><?=csrf_field()?><label class="form-label">Name<input name="name" class="form-control" required></label><label class="form-label mt-2">Description<textarea name="description" class="form-control"></textarea></label><button class="btn btn-success mt-3">Add category</button></form></div></div><div class="col-md-7"><div class="card p-3"><table class="table"><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td class="text-end"><a data-confirm="Delete category?" href="?delete=<?=$r['id']?>" class="btn btn-sm btn-outline-danger">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div></div></main><?php include __DIR__.'/../../includes/footer.php';?>
